// Demo intake — in production this node is swapped for a real form
// trigger (Tally/Typeform/webhook) or a Sheet read of pending
// applications. Emits a realistic batch including the dirty rows
// every real program sees.
return [
  { json: { name: 'Ari Lopez', email: 'ari@example.com', platform: 'instagram', handle: '@ari.moves', followers: 42000,   engagement_rate: 4.8, posts: 210, niche: 'fitness' } },
  { json: { name: 'Bea Kim',   email: 'bea@example.com', platform: 'tiktok',    handle: '@bea.eats',  followers: 12000,   engagement_rate: 6.2, posts: 140, niche: 'cooking' } },
  { json: { name: 'Nate Null',                            platform: 'youtube',   handle: '@nate',      followers: 51000,   engagement_rate: 3.1, posts: 88,  niche: 'tech'    } },
  { json: { name: 'Mia Moon',  email: 'mia@example.com', platform: 'instagram', handle: '@mia.moon',  followers: 2000000, engagement_rate: 9.9, posts: 0,   niche: 'travel'  } },
  { json: { name: 'Ari Again', email: 'ari@example.com', platform: 'instagram', handle: '@ari.alt',   followers: 8000,    engagement_rate: 2.5, posts: 60,  niche: 'fitness' } },
  { json: { name: 'Sam Small', email: 'sam@example.com', platform: 'twitch',    handle: '@sam.plays', followers: 900,     engagement_rate: 1.1, posts: 40,  niche: 'gaming'  } }
];

// Validate + dedupe + score each application.
//
// PROGRAM RULES — edit this block to match your program.
const RULES = {
  accepted_platforms: ['instagram', 'tiktok', 'youtube'],
  min_followers: 5000,
  min_engagement_rate: 2.0,          // percent
  min_posts_for_claimed_reach: 10,   // sanity: a claimed audience with fewer posts is implausible
  min_fit_score: 60                  // 0-100
};

const seen = new Set();
return $input.all().map(({ json: a }) => {
  const email = (a.email || '').toLowerCase().trim();
  let reason = null;

  // 1. Required fields.
  if (!a.name || !email || !a.platform) {
    reason = `missing required field: ${!a.name ? 'name' : !email ? 'email' : 'platform'}`;
  // 2. Dedupe by email within the run.
  } else if (seen.has(email)) {
    reason = `duplicate of ${email} — already seen this run`;
  } else {
    seen.add(email);
    // 3. Sanity-check the self-reported metrics.
    const f = a.followers, e = a.engagement_rate, p = a.posts;
    if (typeof f !== 'number' || typeof e !== 'number' || typeof p !== 'number' || f < 0 || p < 0 || e < 0 || e > 100) {
      reason = 'invalid self-reported metrics (negative, non-numeric or engagement_rate outside 0-100)';
    } else if (f > 0 && p < RULES.min_posts_for_claimed_reach) {
      reason = `implausible metrics: ${f} followers but only ${p} posts`;
    }
  }

  // 4. Score fit against the rules (pure arithmetic, deterministic).
  let fit_score = 0;
  if (!reason) {
    if (RULES.accepted_platforms.includes((a.platform || '').toLowerCase())) fit_score += 30;
    fit_score += Math.min(30, Math.round(30 * a.followers / (4 * RULES.min_followers)));
    fit_score += Math.min(40, Math.round(40 * a.engagement_rate / (3 * RULES.min_engagement_rate)));
    if (fit_score < RULES.min_fit_score) {
      reason = `fit score ${fit_score} below threshold ${RULES.min_fit_score}`;
    }
  }

  return { json: { ...a, email, fit_score, qualified: !reason, reject_reason: reason } };
});

// Personalized outreach draft for a qualified applicant.
// DEMO MODE: composes the draft only. To go live, add a Gmail or
// Send Email node after this one and map `draft` — the shape is
// already correct.
const a = $json;
return {
  json: {
    status: 'qualified',
    applicant: a.name,
    email: a.email,
    fit_score: a.fit_score,
    draft: `Hi ${a.name} — we loved your ${a.niche} content on ${a.platform} (${a.handle}). Your audience of ${a.followers.toLocaleString()} at ${a.engagement_rate}% engagement is a strong fit for our ambassador program (fit score ${a.fit_score}/100). We'd like to invite you to join — reply to this email and we'll send your welcome kit and tracking link.`
  }
};

// Reason-coded owner alert — the failure path is a first-class
// output, not a dropped application.
const a = $json;
return {
  json: {
    status: 'alerted',
    channel: 'owner-alert',
    alert: `Application from ${a.name || 'unknown'} <${a.email || 'no-email'}> NOT qualified: ${a.reject_reason}`
  }
};

// One owner-facing summary per run. Keep AFTER Merge — two
// branches fed in directly would execute this node twice.
const items = $input.all();
const qualified = items.filter(i => i.json.status === 'qualified');
const alerts = items.filter(i => i.json.status === 'alerted');
const lines = alerts.map(i => '  - ' + i.json.alert);
return {
  json: {
    status: 'digest',
    channel: 'owner-digest',
    summary: `Run complete: ${qualified.length} applicant(s) qualified, ${alerts.length} alert(s)`,
    needs_attention: alerts.map(i => i.json.alert),
    detail: qualified.map(i => `  - ${i.json.applicant} <${i.json.email}> — fit ${i.json.fit_score}/100 — outreach draft ready`).concat(lines).join('\n')
  }
};
